{"code": "export async function main(input: unknown) {
  const qs = ["orders.ts", "reserveStock", "deadlock", "DatabaseError"];
  const out: Record<string, unknown> = {};
  for (const q of qs) out[q] = await sdk.linear.searchIssues({ query: q });
  const blame = await sdk.github.getBlame({ file: "src/orders.ts", line: 88 });
  return { out, blame };
}"}

