{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "api" });
  const candidates = issues.filter(i => i.status === "unresolved" && i.count >= 0);

  // Find culprits not mentioned in any Linear issue yet
  const fresh: typeof candidates = [];
  for (const issue of candidates) {
    const byCulprit = await sdk.linear.searchIssues({ query: issue.culprit });
    const byTitle = await sdk.linear.searchIssues({ query: issue.title });
    const mentioned = [...byCulprit.issues, ...byTitle.issues].some(
      l => (l.description ?? "").includes(issue.culprit) || l.title.includes(issue.title) ||
           (issue.culprit && l.title.includes(issue.culprit))
    );
    if (!mentioned) fresh.push(issue);
  }

  // Title of the first such Sentry issue
  const firstTitle = fresh.length > 0 ? fresh[0].title : null;

  const created: { culprit: string; identifier: string; id: string }[] = [];
  for (const issue of fresh) {
    const blame = await sdk.github.getBlame({ file: issue.filename, line: issue.lineNumber });
    const res = await sdk.linear.createIssue({
      title: `[Sentry] ${firstTitle}`,
      description: issue.culprit,
      assigneeEmail: blame.authorEmail,
    });
    created.push({ culprit: issue.culprit, identifier: res.identifier, id: res.id });
  }

  return { checked: candidates.length, created: created.map(c => c.identifier) };
}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "api" });
  const checked = issues.filter(i => i.status === "unresolved" && i.count >= 0);
  const report: unknown[] = [];
  for (const issue of checked) {
    const byCulprit = await sdk.linear.searchIssues({ query: issue.culprit });
    const byTitle = await sdk.linear.searchIssues({ query: issue.title });
    report.push({
      issue: issue.shortId,
      title: issue.title,
      culprit: issue.culprit,
      count: issue.count,
      linearHits: [...byCulprit.issues, ...byTitle.issues].map(l => ({
        identifier: l.identifier, title: l.title, description: l.description,
        mentionsCulprit: (l.description ?? "").includes(issue.culprit),
      })),
    });
  }
  return { checked: checked.length, report };
}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "api" });
  const checkedIssues = issues.filter(i => i.status === "unresolved" && i.count >= 0);

  const fresh: typeof checkedIssues = [];
  for (const issue of checkedIssues) {
    const byCulprit = await sdk.linear.searchIssues({ query: issue.culprit });
    const byTitle = await sdk.linear.searchIssues({ query: issue.title });
    const mentioned = [...byCulprit.issues, ...byTitle.issues].some(
      l => (l.description ?? "").includes(issue.culprit) || l.title.includes(issue.title)
    );
    if (!mentioned) fresh.push(issue);
  }

  const title = fresh.length > 0 ? `[Sentry] ${fresh[0].title}` : null;

  const created: string[] = [];
  for (const issue of fresh) {
    const blame = await sdk.github.getBlame({ file: issue.filename, line: issue.lineNumber });
    const res = await sdk.linear.createIssue({
      title: title as string,
      description: issue.culprit,
      assigneeEmail: blame.authorEmail,
    });
    created.push(res.identifier);
  }

  return { checked: checkedIssues.length, created };
}"}
